import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const DEFAULT_LABELS = ["Background", "Music", "Text", "Voice over"];

const readLabels = (raw: unknown): string[] => {
  const list = Array.isArray(raw)
    ? raw.map((v) => String(v ?? "").trim()).filter((s) => s.length > 0)
    : [];
  return (list.length > 0 ? list : DEFAULT_LABELS).slice(0, 4);
};

// One of four ingredient glyphs, drawn from tokens only. `i` picks the shape so the
// tiles still read as background / music / text / voice when relabelled.
const glyph = (i: number, size: number, accent: string, f: number, muted: string) => {
  if (i % 4 === 0) {
    return (
      <div
        style={{
          width: size,
          height: size * 0.72,
          borderRadius: size * 0.1,
          border: `${Math.max(2, size * 0.045)}px solid ${accent}`,
          background: `repeating-linear-gradient(135deg, ${accent}33 0 ${size * 0.09}px, transparent ${size * 0.09}px ${size * 0.18}px)`,
          position: "relative",
        }}
      >
        <div
          style={{
            position: "absolute",
            top: size * 0.08,
            right: size * 0.1,
            width: size * 0.16,
            height: size * 0.16,
            borderRadius: 999,
            background: COLORS.gold,
          }}
        />
      </div>
    );
  }

  if (i % 4 === 1) {
    return (
      <div style={{ width: size, height: size * 0.72, display: "flex", alignItems: "flex-end", gap: size * 0.08 }}>
        {[0, 1, 2, 3].map((b) => (
          <div
            key={b}
            style={{
              flex: 1,
              height: size * (0.22 + 0.5 * Math.abs(Math.sin(f * 0.22 + b * 0.9))),
              borderRadius: size * 0.04,
              background: accent,
            }}
          />
        ))}
      </div>
    );
  }

  if (i % 4 === 2) {
    return (
      <div
        style={{
          width: size,
          height: size * 0.72,
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          gap: size * 0.11,
        }}
      >
        {[1, 0.78, 0.54].map((w, b) => (
          <div
            key={b}
            style={{
              width: `${w * 100}%`,
              height: size * 0.1,
              borderRadius: 999,
              background: b === 0 ? accent : muted,
            }}
          />
        ))}
      </div>
    );
  }

  return (
    <div style={{ width: size, height: size * 0.72, display: "flex", alignItems: "center", gap: size * 0.06 }}>
      {[0, 1, 2, 3, 4, 5].map((b) => (
        <div
          key={b}
          style={{
            flex: 1,
            height: size * (0.14 + 0.56 * Math.abs(Math.sin(f * 0.3 + b * 0.6))),
            borderRadius: 999,
            background: b % 2 === 0 ? accent : `${accent}88`,
          }}
        />
      ))}
    </div>
  );
};

const StoryElementsMerge: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const total = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const params = (anim.params ?? {}) as Record<string, unknown>;
  const title = String(params.title ?? anim.text ?? "");
  const result = String(params.result ?? "Final story");
  const labels = readLabels(params.labels);
  const n = labels.length;

  const W = frame.width;
  const H = frame.height;
  const textColor = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const mutedColor = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  // Portrait stacks the tiles in a 2-column grid; half and landscape flatten them
  // into a single row (a tall stack overflows a 960px-high or 16:9 box).
  const L =
    format === "portrait"
      ? {
          tileW: W * 0.36,
          glyphSize: W * 0.13,
          label: W * 0.032,
          cols: Math.min(2, n),
          titleTop: H * 0.09,
          titleSize: W * 0.075,
          cy: H * 0.52,
          resultW: W * 0.74,
          resultSize: W * 0.066,
        }
      : format === "half"
        ? {
            tileW: W * 0.2,
            glyphSize: W * 0.072,
            label: W * 0.019,
            cols: n,
            titleTop: H * 0.06,
            titleSize: W * 0.05,
            cy: H * 0.6,
            resultW: W * 0.6,
            resultSize: W * 0.045,
          }
        : {
            tileW: W * 0.17,
            glyphSize: W * 0.058,
            label: W * 0.017,
            cols: n,
            titleTop: H * 0.1,
            titleSize: W * 0.045,
            cy: H * 0.56,
            resultW: W * 0.52,
            resultSize: W * 0.04,
          };

  const cols = Math.max(1, L.cols);
  const rows = Math.ceil(n / cols);
  const gapX = L.tileW + W * 0.05;
  const nominalH = L.tileW * 0.72;
  const gapY = nominalH + H * 0.03;

  const mergeAt = total * 0.62;
  const titleIn = interpolate(f, [0, Math.max(5, total * 0.09)], [0, 1], {
    ...CLAMP,
    easing: Easing.out(Easing.cubic),
  });
  const pop = spring({ frame: f - mergeAt, fps, config: { damping: 13, mass: 0.8 } });
  const flash = interpolate(f, [mergeAt, mergeAt + total * 0.05, mergeAt + total * 0.2], [0, 0.85, 0], CLAMP);
  const flashScale = interpolate(f, [mergeAt, mergeAt + total * 0.2], [0.25, 1.35], {
    ...CLAMP,
    easing: Easing.out(Easing.cubic),
  });

  const resultFont =
    result.length > 34 ? L.resultSize * 0.6 : result.length > 20 ? L.resultSize * 0.78 : L.resultSize;

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.body }}>
      {title.length > 0 ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: L.titleTop,
            display: "flex",
            justifyContent: "center",
            opacity: titleIn,
            translate: `0px ${(1 - titleIn) * -L.titleSize * 0.4}px`,
          }}
        >
          <span
            style={{
              fontFamily: FONTS.display,
              fontWeight: FONTS.displayWeight,
              fontSize: title.length > 30 ? L.titleSize * 0.72 : title.length > 18 ? L.titleSize * 0.86 : L.titleSize,
              lineHeight: 0.95,
              textTransform: "uppercase",
              letterSpacing: "0.01em",
              textAlign: "center",
              maxWidth: W * 0.86,
              backgroundImage: headlineGradient(),
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              color: "transparent",
            }}
          >
            {title}
          </span>
        </div>
      ) : null}

      {labels.map((label, i) => {
        const accent = [COLORS.teal, COLORS.leather, COLORS.gold, COLORS.tealBright][i % 4];
        const appear = total * 0.05 + i * total * 0.07;
        const inT = interpolate(f, [appear, appear + total * 0.14], [0, 1], {
          ...CLAMP,
          easing: Easing.out(Easing.cubic),
        });
        const conv = interpolate(f, [total * 0.38 + i * total * 0.015, mergeAt], [0, 1], {
          ...CLAMP,
          easing: Easing.inOut(Easing.cubic),
        });
        const fade = interpolate(conv, [0.55, 1], [1, 0], CLAMP);

        const col = i % cols;
        const row = Math.floor(i / cols);
        const inRow = Math.min(cols, n - row * cols);
        const ox = (col - (inRow - 1) / 2) * gapX * (1 - conv);
        const oy = (row - (rows - 1) / 2) * gapY * (1 - conv);

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: W / 2,
              top: L.cy,
              width: L.tileW,
              opacity: inT * fade,
              transform: `translate(${ox}px, ${oy + (1 - inT) * nominalH * 0.22}px) translate(-50%, -50%) scale(${(0.86 + 0.14 * inT) * (1 - 0.7 * conv)})`,
              willChange: "transform",
            }}
          >
            <div
              style={{
                boxSizing: "border-box",
                width: "100%",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: L.glyphSize * 0.26,
                padding: L.glyphSize * 0.3,
                background: COLORS.vellum,
                border: `${Math.max(2, L.glyphSize * 0.035)}px solid ${accent}66`,
                borderRadius: L.tileW * 0.09,
                boxShadow: ENGRAVE_SHADOW,
              }}
            >
              {glyph(i, L.glyphSize, accent, f, mutedColor)}
              <span
                style={{
                  fontFamily: FONTS.body,
                  fontWeight: 600,
                  fontSize: label.length > 24 ? L.label * 0.74 : label.length > 14 ? L.label * 0.86 : L.label,
                  lineHeight: 1.2,
                  letterSpacing: "0.12em",
                  textTransform: "uppercase",
                  textAlign: "center",
                  color: textColor,
                }}
              >
                {label}
              </span>
            </div>
          </div>
        );
      })}

      <div
        style={{
          position: "absolute",
          left: W / 2,
          top: L.cy,
          width: Math.min(W, H) * 0.42,
          height: Math.min(W, H) * 0.42,
          borderRadius: 999,
          border: `${Math.max(2, Math.min(W, H) * 0.006)}px solid ${COLORS.tealBright}`,
          opacity: flash,
          transform: `translate(-50%, -50%) scale(${flashScale})`,
        }}
      />

      {f >= mergeAt ? (
        <div
          style={{
            position: "absolute",
            left: W / 2,
            top: L.cy,
            width: L.resultW,
            opacity: interpolate(pop, [0, 0.4], [0, 1], CLAMP),
            transform: `translate(-50%, -50%) scale(${0.7 + 0.3 * pop})`,
          }}
        >
          <div
            style={{
              boxSizing: "border-box",
              width: "100%",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: resultFont * 0.42,
              padding: `${resultFont * 0.7}px ${resultFont * 0.8}px`,
              background: COLORS.vellum,
              border: `${Math.max(2, resultFont * 0.05)}px solid ${COLORS.teal}`,
              borderRadius: L.resultW * 0.05,
              boxShadow: ENGRAVE_SHADOW,
            }}
          >
            <div style={{ display: "flex", gap: resultFont * 0.3 }}>
              {labels.map((_, i) => (
                <div
                  key={i}
                  style={{
                    width: resultFont * 0.2,
                    height: resultFont * 0.2,
                    borderRadius: 999,
                    background: [COLORS.teal, COLORS.leather, COLORS.gold, COLORS.tealBright][i % 4],
                    opacity: interpolate(pop, [0.2 + i * 0.12, 0.6 + i * 0.12], [0, 1], CLAMP),
                  }}
                />
              ))}
            </div>
            <span
              style={{
                fontFamily: FONTS.display,
                fontWeight: FONTS.displayWeight,
                fontSize: resultFont,
                lineHeight: 0.98,
                textTransform: "uppercase",
                letterSpacing: "0.01em",
                textAlign: "center",
                backgroundImage: headlineGradient(),
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                color: "transparent",
              }}
            >
              {result}
            </span>
          </div>
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

export default StoryElementsMerge;
